<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Csrf;use App\Core\Database;use App\Services\DanceCupScoringService;
$pdo=Database::connection();$test=(string)($_GET['data_mode']??$_POST['data_mode']??'')==='test';$p=$test?'bdc_test_dance_cup':'bdc_dance_cup';$t=DanceCupScoringService::tables($test);$token=preg_replace('/[^a-f0-9]/','',(string)($_GET['token']??$_POST['token']??''));if(strlen($token)!==64){http_response_code(404);exit('Judge link not found.');}DanceCupScoringService::ensureWorkspaceTables($pdo,$test);
$load=static function()use($pdo,$p,$t,$token){$q=$pdo->prepare("SELECT s.*,j.judge_name,j.is_chief,j.judge_order,c.category_name,c.round_name,c.dance_style,c.competition_level,e.name event_name FROM {$p}_judge_sessions s JOIN {$p}_judges j ON j.id=s.judge_assignment_id JOIN {$t['competitions']} c ON c.id=s.competition_id JOIN {$t['events']} e ON e.id=c.event_id WHERE s.access_token=:token LIMIT 1");$q->execute(['token'=>$token]);return $q->fetch();};$session=$load();if(!$session){http_response_code(404);exit('Judge link not found or replaced.');}$error='';$notice='';$locked=$session['status']==='submitted';
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Security check failed. Reload and try again.');if($locked)throw new RuntimeException('Your scoring is submitted and locked. Ask the scorer to reopen it.');$marks=(array)($_POST['mark']??[]);$criteriaQ=$pdo->prepare("SELECT id,maximum_points FROM {$t['criteria']} WHERE competition_id=:id");$criteriaQ->execute(['id'=>$session['competition_id']]);$limits=[];foreach($criteriaQ->fetchAll() as $x)$limits[(int)$x['id']]=(float)$x['maximum_points'];$entriesQ=$pdo->prepare("SELECT id FROM {$p}_entries WHERE competition_id=:id AND status='active'");$entriesQ->execute(['id'=>$session['competition_id']]);$entryIds=array_map('intval',$entriesQ->fetchAll(PDO::FETCH_COLUMN));$pdo->beginTransaction();$up=$pdo->prepare("INSERT INTO {$p}_marks(competition_id,entry_id,judge_id,criterion_id,points) VALUES(:c,:e,:j,:criterion,:points) ON DUPLICATE KEY UPDATE points=VALUES(points),updated_at=NOW()");$saved=0;foreach($entryIds as $entryId)foreach($limits as $criterionId=>$maximum){$raw=$marks[$entryId][$criterionId]??null;if($raw===null||$raw==='')continue;$points=(float)$raw;if($points<0||$points>$maximum)throw new RuntimeException('A score is outside its allowed criterion maximum.');$up->execute(['c'=>$session['competition_id'],'e'=>$entryId,'j'=>$session['judge_assignment_id'],'criterion'=>$criterionId,'points'=>$points]);$saved++;}$action=(string)($_POST['action']??'save');if($action==='submit'){$required=count($entryIds)*count($limits);if($saved<$required){$existing=$pdo->prepare("SELECT COUNT(*) FROM {$p}_marks WHERE competition_id=:c AND judge_id=:j");$existing->execute(['c'=>$session['competition_id'],'j'=>$session['judge_assignment_id']]);if((int)$existing->fetchColumn()<$required)throw new RuntimeException('Complete every score before submitting.');}$pdo->prepare("UPDATE {$p}_judge_sessions SET status='submitted',submitted_at=NOW(),last_seen_at=NOW(),started_at=COALESCE(started_at,NOW()) WHERE id=:id")->execute(['id'=>$session['id']]);$notice='Scores submitted and locked.';}else{$pdo->prepare("UPDATE {$p}_judge_sessions SET status='scoring',last_seen_at=NOW(),started_at=COALESCE(started_at,NOW()) WHERE id=:id")->execute(['id'=>$session['id']]);$notice='Score draft saved.';}$pdo->commit();$session=$load();$locked=$session['status']==='submitted';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
$q=$pdo->prepare("SELECT * FROM {$t['criteria']} WHERE competition_id=:id ORDER BY sort_order,id");$q->execute(['id'=>$session['competition_id']]);$criteria=$q->fetchAll();$q=$pdo->prepare("SELECT * FROM {$p}_entries WHERE competition_id=:id AND status='active' ORDER BY bib_number,id");$q->execute(['id'=>$session['competition_id']]);$entries=$q->fetchAll();$q=$pdo->prepare("SELECT entry_id,criterion_id,points FROM {$p}_marks WHERE competition_id=:c AND judge_id=:j");$q->execute(['c'=>$session['competition_id'],'j'=>$session['judge_assignment_id']]);$values=[];foreach($q->fetchAll() as $m)$values[(int)$m['entry_id']][(int)$m['criterion_id']]=$m['points'];$required=count($entries)*count($criteria);$completed=0;foreach($entries as $entry)foreach($criteria as $criterion)if(isset($values[$entry['id']][$criterion['id']]))$completed++;$csrf=Csrf::token();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($session['category_name'])?> · Judge Scoring</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=354" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=325"></script><style>body{background:#f1f5f9}.judge-hero{background:linear-gradient(135deg,#111d35,#601a36);color:#fff}.entry-card{border:0;border-radius:18px;box-shadow:0 8px 22px rgba(15,23,42,.08)}.criteria-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:.75rem}.score-box label{font-size:.8rem;font-weight:700}.score-box input{font-size:1.15rem;font-weight:700}.submit-dock{position:sticky;bottom:0;background:rgba(241,245,249,.94);backdrop-filter:blur(12px);z-index:5}@media(max-width:575px){.criteria-grid{grid-template-columns:1fr 1fr}.judge-hero h1{font-size:1.35rem}}</style></head><body><header class="judge-hero py-4"><div class="container" style="max-width:1100px"><span class="badge text-bg-warning"><?=$test?'TEST · ':''?>DANCE CUP</span><h1 class="h2 mt-2 mb-1"><?=e($session['category_name'])?></h1><div><?=e($session['event_name'])?> · <?=e(ucfirst($session['round_name']))?></div><div class="mt-2"><strong>J<?=(int)$session['judge_order']?> · <?=e($session['judge_name'])?></strong><?=$session['is_chief']?' · ★ Chief Judge':''?></div></div></header><main class="container py-4" style="max-width:1100px"><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><section class="card border-0 shadow-sm mb-4"><div class="card-body"><div class="d-flex justify-content-between"><strong>Scoring progress</strong><span><?=$completed?> / <?=$required?></span></div><div class="progress mt-2" style="height:10px"><div class="progress-bar bg-success" style="width:<?=$required?round($completed/$required*100):0?>%"></div></div></div></section><?php if(!$entries):?><div class="alert alert-warning">The scorer has not added competitors yet.</div><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="token" value="<?=e($token)?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><?php foreach($entries as $entry):?><article class="card entry-card mb-3"><div class="card-body p-3 p-md-4"><div class="d-flex align-items-baseline gap-3 mb-3"><span class="display-6 fw-bold text-primary">#<?=(int)$entry['bib_number']?></span><h2 class="h4 mb-0"><?=e($entry['display_name'])?></h2></div><div class="criteria-grid"><?php foreach($criteria as $criterion):$v=$values[$entry['id']][$criterion['id']]??'';?><div class="score-box"><label class="form-label"><?=e($criterion['criterion_name'])?> <span class="text-muted">/ <?=e(rtrim(rtrim(number_format((float)$criterion['maximum_points'],2,'.',''),'0'),'.'))?></span></label><input class="form-control" type="number" min="0" max="<?=e($criterion['maximum_points'])?>" step="0.01" name="mark[<?=$entry['id']?>][<?=$criterion['id']?>]" value="<?=e((string)$v)?>" <?=$locked?'disabled':''?> required></div><?php endforeach;?></div></div></article><?php endforeach;?><div class="submit-dock py-3"><div class="d-flex gap-2"><?php if(!$locked):?><button class="btn btn-outline-primary btn-lg flex-fill" name="action" value="save">Save Draft</button><button class="btn btn-success btn-lg flex-fill" name="action" value="submit" onclick="return confirm('Submit and lock all your Dance Cup scores?')">Submit Scores</button><?php else:?><div class="alert alert-success w-100 mb-0 text-center fw-bold">Submitted · scoring locked</div><?php endif;?></div></div></form><?php endif;?></main></body></html>
